from collections import defaultdict

def has_cycle_undirected(n, edges):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    seen = [False] * n

    def dfs(u, parent):
        seen[u] = True
        for v in g[u]:
            if not seen[v]:
                if dfs(v, u):
                    return True
            elif v != parent:
                return True
        return False

    for u in range(n):
        if not seen[u] and dfs(u, -1):
            return True
    return False

def has_cycle_dsu(n, edges):
    p = list(range(n))
    def find(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru == rv:
            return True
        p[rv] = ru
    return False
